const temas=["Information map", "Information and permissions", "Providers", "Security and response", "Application and follow-up"];const pasos=["Prepare a map of the data you use, its purposes, the people involved and the internal owners.", "Review the privacy notices and the legal basis that allows each use of data.", "Identify which providers receive or access data and review the applicable clauses.", "Define who manages access, requests from individuals and incidents, and how the response will be documented.", "Organize training and a review of evidence of application."];
document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const values=temas.map((_,i)=>$('q'+i).value);const r=TempoTools.diagnostico(values);if(!r)return;const pending=r.filter(x=>x.value!=='si');show('<p class="eyebrow">Your next step</p><h2>'+(pending.length?'An agenda to review with your team':'Review the evidence of what you already apply')+'</h2><p>'+(pending.length?'These answers point to aspects to clarify or complete; they do not prove an infringement.':'You indicate that you have measures in all five points. Their scope and evidence need to be reviewed to assess compliance.')+'</p><ul>'+r.map(x=>'<li><strong>'+temas[x.index]+': </strong>'+(x.value==='si'?'Keep and review the evidence that supports your answer.':pasos[x.index])+(x.value==='nose'?' Start by confirming what currently exists.':'')+'</li>').join('')+'</ul><p>This guidance does not determine whether you need a DPO or whether an impact assessment is required. You can review those questions with your adviser or with our DPO and large-scale tool.</p>'+finish());});